import { requireVendorSession } from "../../../../../lib/vendor-session";
import { createVendorMediaUploadIntent } from "../../../../../lib/media-upload-service";
export async function POST(request:Request){try{const principal=await requireVendorSession(request,true);const body=await request.json();const kind=String(body.kind??"") as "image"|"video"|"document";if(!["image","video","document"].includes(kind))throw new Error("Invalid media kind");return Response.json(await createVendorMediaUploadIntent(principal,{canonicalVariantId:String(body.canonicalVariantId??"").trim(),kind,filename:String(body.filename??""),contentType:String(body.contentType??""),byteSize:Number(body.byteSize),altText:String(body.altText??"").trim()||undefined,rightsOwner:String(body.rightsOwner??"").trim()}));}catch(e){return Response.json({error:e instanceof Error?e.message:"media_intent_failed"},{status:400})}}
